def main():
    assert len(SOURCES) == 20
    assert {a['number'] for a in SOURCES} == set(DRAFTS)
    result = []
    for source in SOURCES:
        entry = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
        entry.update(DRAFTS[source['number']])
        entry['status'] = 'rewrite_draft'
        result.append(entry)
    Path('answer.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
    print(f'answer.json : {len(result)} articles')


if __name__ == '__main__':
    main()
